ep_restock_script.versaScript:
json_xml import *;
vdb import *;
http import *;
email import *;
crypto import *;
jwt import *;
time import *;
datetime import *;

let p = params;
let claims = p.auth;
let actor = claims.username;
if (actor == "") {
  actor = claims.sub;
}
if (actor == "") {
  actor = "anonymous";
}
let role = claims.role;
if (role == "") {
  role = "USER";
}
let allowed = role == "SUPER_ADMIN" || role == "WAREHOUSE_MANAGER";
if (!allowed) {
  {authorized: false, reason: "Role does not permit restock", actor: actor, role: role};
} else {
  let sku = p.sku;
  if (sku == "") {
    {authorized: true, updated: false, reason: "sku is required", actor: actor};
  } else {
    let delta = p.delta;
    if (delta == "") {
      delta = 0;
    }
    let items = vdb.collection("inventory_items");
    let found = items.find({sku: {$eq: sku}}, 1);
    let rows = found.data;
    if (leng(rows) == 0) {
      {authorized: true, updated: false, reason: "Inventory item not found", sku: sku, actor: actor};
    } else {
      let current = rows[0];
      let currentQty = current.quantity;
      if (currentQty == "") {
        currentQty = 0;
      }
      let nextQty = currentQty + delta;
      let updateResult = items.update({sku: {$eq: sku}}, {quantity: nextQty, updatedBy: actor, updatedAt: time.time()});
      let updated = true;
      if (updateResult.ok == false) {
        updated = false;
      }
      {authorized: true, updated: updated, sku: sku, previousQuantity: currentQty, delta: delta, quantity: nextQty, actor: actor, role: role, updateResult: updateResult};
    }
  }
}

